// notify-worker — single-file version for the Supabase dashboard editor (generated by scripts/build_deploy.py)
// ---- inlined from _shared/templates.ts
// Email templates. Customer emails are in English; internal emails in Spanish.
// Never include shipping costs or internal notes in customer emails.

const esc = (s: unknown) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c] as string));
const CARRIER_URL: Record<string, (t: string) => string> = {
  UPS: (t) => `https://www.ups.com/track?tracknum=${encodeURIComponent(t)}`,
  FEDEX: (t) => `https://www.fedex.com/fedextrack/?trknbr=${encodeURIComponent(t)}`,
  USPS: (t) => `https://tools.usps.com/go/TrackConfirmAction?tLabels=${encodeURIComponent(t)}`,
  DHL: (t) => `https://www.dhl.com/us-en/home/tracking.html?tracking-id=${encodeURIComponent(t)}`,
};

const CUSTOMER: Record<string, { subject: string; lead: string }> = {
  request_confirmed: { subject: 'We received your sample request', lead: 'Thank you. We received your sample request and reserved the samples you selected.' },
  samples_prepared: { subject: 'Your samples are prepared', lead: 'Your samples have been prepared and packed.' },
  tracking_registered: { subject: 'Tracking number for your samples', lead: 'A shipping label was created for your samples.' },
  shipped: { subject: 'Your samples have shipped', lead: 'Your samples were handed to the carrier.' },
  ready_for_pickup: { subject: 'Your samples are ready for pickup', lead: 'Your samples are ready for pickup at our warehouse.' },
  delivered: { subject: 'Your samples were delivered', lead: 'The carrier reports your samples as delivered.' },
  collected: { subject: 'Your samples were picked up', lead: 'Your samples were picked up. Thank you.' },
  cancelled: { subject: 'Your sample request was cancelled', lead: 'Your sample request was cancelled. If this is unexpected, please reply to this email.' },
};
const INTERNAL: Record<string, string> = {
  request_confirmed: 'Nueva solicitud de muestras', samples_prepared: 'Muestras preparadas', tracking_registered: 'Guía registrada',
  shipped: 'Pedido enviado', ready_for_pickup: 'Disponible para recoger', delivered: 'Pedido entregado', collected: 'Pedido recogido',
  cancelled: 'Solicitud cancelada', incident: 'Incidencia registrada', invoice_document: 'Documento de facturación disponible',
};

function shell(title: string, body: string) {
  return `<!doctype html><html><body style="margin:0;background:#f4f4f2;font-family:Montserrat,Arial,sans-serif;color:#191d20">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:24px 12px">
<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;background:#ffffff;border:1px solid #e3e1dc">
<tr><td style="background:#191d20;color:#ffffff;padding:20px 28px;font-size:18px;letter-spacing:.18em;font-weight:600">CESANTONI</td></tr>
<tr><td style="padding:28px"><h1 style="font-size:20px;margin:0 0 16px">${esc(title)}</h1>${body}</td></tr>
<tr><td style="padding:16px 28px;border-top:1px solid #e3e1dc;font-size:12px;color:#6b6b6b">CESANTONI Samples · This message was sent automatically.</td></tr>
</table></td></tr></table></body></html>`;
}

function render(n: any, opts: { siteUrl: string; trackToken?: string }) {
  const r = n.request || {};
  const lines = (r.lines || []).map((l: any) => `<tr><td style="padding:6px 0;border-bottom:1px solid #eee">${esc(l.description)}</td><td align="right" style="padding:6px 0;border-bottom:1px solid #eee">${esc(l.quantity)}</td></tr>`).join('');
  const table = lines ? `<table width="100%" cellpadding="0" cellspacing="0" style="font-size:14px;margin:16px 0">${lines}</table>` : '';
  const ship = (r.shipments || [])[0] || (n.payload?.tracking_no ? { carrier: n.payload.carrier, tracking_no: n.payload.tracking_no } : null);
  if (n.audience === 'customer') {
    const t = CUSTOMER[n.event];
    if (!t) throw new Error(`no customer template for ${n.event}`);
    const track = opts.trackToken ? `${opts.siteUrl.replace(/\/$/, '')}/track/?f=${encodeURIComponent(r.folio)}&t=${encodeURIComponent(opts.trackToken)}` : null;
    const carrier = ship && ['tracking_registered', 'shipped', 'delivered'].includes(n.event)
      ? `<p style="font-size:14px">Carrier: <b>${esc(ship.carrier)}</b><br>Tracking number: <b>${CARRIER_URL[ship.carrier] ? `<a href="${CARRIER_URL[ship.carrier](ship.tracking_no)}">${esc(ship.tracking_no)}</a>` : esc(ship.tracking_no)}</b></p>` : '';
    const html = shell(t.subject, `<p style="font-size:14px">Hello ${esc(r.full_name)},</p><p style="font-size:14px">${esc(t.lead)}</p>
<p style="font-size:14px">Request number: <b>${esc(r.folio)}</b></p>${carrier}${table}
${track ? `<p><a href="${track}" style="display:inline-block;background:#191d20;color:#fff;padding:12px 20px;text-decoration:none;font-size:14px">Track your request</a></p>` : ''}`);
    const text = `Hello ${r.full_name},\n\n${t.lead}\n\nRequest number: ${r.folio}\n${ship ? `Carrier: ${ship.carrier} · Tracking: ${ship.tracking_no}\n` : ''}${(r.lines || []).map((l: any) => `- ${l.description} × ${l.quantity}`).join('\n')}\n${track ? `\nTrack your request: ${track}\n` : ''}`;
    return { subject: `${t.subject} · ${r.folio}`, html, text };
  }
  const title = INTERNAL[n.event] || n.event;
  const extra = n.payload?.description || n.payload?.reason ? `<p style="font-size:14px">${esc(n.payload.description || n.payload.reason)}</p>` : '';
  const html = shell(`${title} · ${r.folio}`, `<p style="font-size:14px">Folio <b>${esc(r.folio)}</b> · ${esc(r.full_name)}${r.company ? ' · ' + esc(r.company) : ''}<br>
Entrega: ${r.delivery_method === 'pickup' ? 'Recolección en almacén' : 'Paquetería'} · Estatus: ${esc(r.status)}</p>${extra}${table}
<p><a href="${opts.siteUrl.replace(/\/$/, '')}/admin/#/requests/${encodeURIComponent(r.folio)}">Abrir en la plataforma</a></p>`);
  return { subject: `${title} · ${r.folio}`, html, text: `${title} · ${r.folio}\n${opts.siteUrl}/admin/` };
}

// ---- inlined from _shared/request.ts
// Shared, dependency-free logic used by the Edge Functions (Deno) and by the local test server (Node).
// Only erasable TypeScript syntax is used so Node can run it with --experimental-strip-types.

type Line = { sku_code: string; quantity: number };
type Payload = {
  full_name: string; company: string | null; email: string; phone: string;
  delivery_method: 'shipping' | 'pickup';
  address_line: string | null; city: string | null; state: string | null; zip_code: string | null; country: string | null;
  delivery_notes: string | null; project_name: string | null; notes: string | null;
  billing: Record<string, string> | null; lines: Line[];
};

const EMAIL = /^[^\s@,;]+@[^\s@,;]+\.[^\s@,;]{2,}$/;
const clean = (v: unknown, max: number): string | null => {
  if (v === undefined || v === null) return null;
  const s = String(v).replace(/[\u0000-\u001f\u007f]/g, ' ').replace(/\s+/g, ' ').trim();
  return s ? s.slice(0, max) : null;
};

// Returns field errors in English (shown to the customer as they are).
function validateRequest(body: any): { payload?: Payload; errors: Record<string, string> } {
  const e: Record<string, string> = {};
  if (!body || typeof body !== 'object') return { errors: { form: 'Invalid request.' } };
  const method = body.delivery_method === 'pickup' ? 'pickup' : body.delivery_method === 'shipping' ? 'shipping' : null;
  const p: Payload = {
    full_name: clean(body.full_name, 120) || '', company: clean(body.company, 120), email: (clean(body.email, 160) || '').toLowerCase(),
    phone: clean(body.phone, 40) || '', delivery_method: (method || 'shipping'),
    address_line: clean(body.address_line, 200), city: clean(body.city, 80), state: clean(body.state, 80),
    zip_code: clean(body.zip_code, 20), country: clean(body.country, 80), delivery_notes: clean(body.delivery_notes, 300),
    project_name: clean(body.project_name, 120), notes: clean(body.notes, 1000), billing: null, lines: [],
  };
  if (p.full_name.length < 2) e.full_name = 'Please enter your full name.';
  if (!EMAIL.test(p.email)) e.email = 'Please enter a valid email address.';
  if (p.phone.replace(/\D/g, '').length < 7) e.phone = 'Please enter a valid phone number.';
  if (!method) e.delivery_method = 'Choose shipping or customer pickup.';
  if (method === 'shipping') {
    for (const [k, label] of [['address_line', 'shipping address'], ['city', 'city'], ['state', 'state'], ['zip_code', 'ZIP code'], ['country', 'country']] as const) {
      if (!p[k]) e[k] = `Please enter the ${label}.`;
    }
  } else {
    // pickup: no shipping address is stored
    p.address_line = p.city = p.state = p.zip_code = p.country = p.delivery_notes = null;
  }
  if (body.billing && typeof body.billing === 'object' && body.billing.required === true) {
    const b = { company: clean(body.billing.company, 160), tax_id: clean(body.billing.tax_id, 40), address: clean(body.billing.address, 300),
                email: (clean(body.billing.email, 160) || '').toLowerCase() };
    if (!b.company) e['billing.company'] = 'Please enter the billing company.';
    if (b.email && !EMAIL.test(b.email)) e['billing.email'] = 'Please enter a valid billing email.';
    p.billing = Object.fromEntries(Object.entries(b).filter(([, v]) => v)) as Record<string, string>;
  }
  const lines = Array.isArray(body.lines) ? body.lines : [];
  const seen = new Set<string>();
  for (const l of lines.slice(0, 31)) {
    const code = String(l?.sku_code || '').trim().toUpperCase();
    const qty = Number(l?.quantity);
    if (!/^[A-Z0-9][A-Z0-9._-]{2,40}$/.test(code) || !Number.isInteger(qty) || qty < 1 || qty > 500 || seen.has(code)) {
      e.lines = 'Your selection contains an invalid item. Please review it.'; continue;
    }
    seen.add(code); p.lines.push({ sku_code: code, quantity: qty });
  }
  if (!p.lines.length && !e.lines) e.lines = 'Please select at least one sample.';
  if (lines.length > 30) e.lines = 'You can request up to 30 different samples.';
  return Object.keys(e).length ? { errors: e } : { payload: p, errors: {} };
}

// Anti-bot checks that need no third party: hidden field must stay empty, and a human needs a few seconds.
function looksAutomated(body: any, now = Date.now()): boolean {
  if (body?.website) return true;
  const started = Number(body?.form_started_at);
  return !Number.isFinite(started) || now - started < 3000 || now - started > 6 * 3600 * 1000;
}

const enc = new TextEncoder();
const hex = (b: ArrayBuffer) => [...new Uint8Array(b)].map((x) => x.toString(16).padStart(2, '0')).join('');
async function sha256Hex(s: string): Promise<string> { return hex(await crypto.subtle.digest('SHA-256', enc.encode(s))); }
async function hmacHex(secret: string, msg: string): Promise<string> {
  const k = await crypto.subtle.importKey('raw', enc.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  return hex(await crypto.subtle.sign('HMAC', k, enc.encode(msg)));
}
// The tracking token is derived from the idempotency key: a retried submission gets the same link
// without the database ever storing the token itself (only its SHA-256).
async function trackingToken(secret: string, idempotencyKey: string): Promise<string> {
  return (await hmacHex(secret, 'track:' + idempotencyKey)).slice(0, 48);
}

// Maps database errors to HTTP answers for the public form (English).
function mapDbError(err: { message?: string; code?: string; details?: string; detail?: string }): { status: number; body: any } {
  const msg = err.message || '';
  if (msg.includes('UNAVAILABLE')) {
    let problems = [];
    try { problems = JSON.parse(err.details || err.detail || '[]'); } catch { /* ignore */ }
    return { status: 409, body: { error: 'availability_changed', message: 'Availability changed for some samples. Please review your selection.', problems } };
  }
  if (msg.includes('RATE_LIMITED')) return { status: 429, body: { error: 'rate_limited', message: 'Too many requests. Please try again later.' } };
  if (msg.startsWith('VALIDATION') || err.code === '22023' || err.code === '23514')
    return { status: 400, body: { error: 'validation', message: 'Some information is not valid. Please review the form.' } };
  return { status: 500, body: { error: 'server', message: 'We could not submit your request. Please try again in a few minutes.' } };
}

// ---- function
// Processes the notifications outbox. Invoked every minute by pg_cron (supabase/deploy/cron.sql),
// so emails go out even when nobody has the platform open.
// Secrets: SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY, WORKER_SECRET, RESEND_API_KEY, MAIL_FROM, MAIL_REPLY_TO,
//          PUBLIC_SITE_URL, TRACKING_SECRET, MAIL_MODE ("test" | "production"), MAIL_TEST_RECIPIENTS (comma separated)

const env = (k: string) => Deno.env.get(k) || '';
const rpc = (fn: string, args: unknown) => fetch(`${env('SUPABASE_URL')}/rest/v1/rpc/${fn}`, {
  method: 'POST', body: JSON.stringify(args),
  headers: { apikey: env('SUPABASE_SERVICE_ROLE_KEY'), Authorization: `Bearer ${env('SUPABASE_SERVICE_ROLE_KEY')}`, 'content-type': 'application/json' },
});

Deno.serve(async (req) => {
  if (req.headers.get('x-worker-secret') !== env('WORKER_SECRET') || !env('WORKER_SECRET')) return new Response('forbidden', { status: 403 });
  const claimed = await rpc('notifications_claim', { p_batch: 25 });
  if (!claimed.ok) return new Response(await claimed.text(), { status: 500 });
  const items: any[] = await claimed.json();
  const testMode = env('MAIL_MODE') !== 'production';
  const testList = env('MAIL_TEST_RECIPIENTS').split(',').map((s) => s.trim()).filter(Boolean);
  let sent = 0, failed = 0;
  for (const raw of items) {
    const n = raw.notifications_claim ?? raw;
    try {
      const token = n.audience === 'customer' && n.request?.source === 'web' ? await trackingToken(env('TRACKING_SECRET'), n.request.idempotency_key) : undefined;
      const mail = render(n, { siteUrl: env('PUBLIC_SITE_URL'), trackToken: token });
      // TEST mode: real recipients are never contacted; the message goes to the authorized test inbox(es)
      const to = testMode ? testList : [n.recipient];
      if (!to.length) throw new Error('MAIL_MODE=test and MAIL_TEST_RECIPIENTS is empty');
      const r = await fetch('https://api.resend.com/emails', {
        method: 'POST',
        headers: { Authorization: `Bearer ${env('RESEND_API_KEY')}`, 'content-type': 'application/json', 'Idempotency-Key': n.dedupe_key.slice(0, 256) },
        body: JSON.stringify({ from: env('MAIL_FROM'), reply_to: env('MAIL_REPLY_TO') || undefined, to,
          subject: (testMode ? `[TEST → ${n.recipient}] ` : '') + mail.subject, html: mail.html, text: mail.text,
          tags: [{ name: 'event', value: n.event }] }),
      });
      const body = await r.json().catch(() => ({}));
      if (!r.ok) throw new Error(`provider ${r.status}: ${JSON.stringify(body).slice(0, 300)}`);
      await rpc('notifications_result', { p_id: n.id, p_ok: true, p_provider_id: body.id ?? null });   // accepted ≠ delivered
      sent++;
    } catch (e) {
      await rpc('notifications_result', { p_id: n.id, p_ok: false, p_error: String((e as Error).message || e) });
      failed++;
    }
  }
  return new Response(JSON.stringify({ claimed: items.length, accepted: sent, failed }), { headers: { 'content-type': 'application/json' } });
});
